    l=0
    r=N-1
    total=0
    if K>=N:
        return SA[N-1] ** A
    mod=10**9 + 7
    multiples = [0]*(N+1)
    multiples[1] = (SA[0] ** (A - 1) % mod) ** (A - 1) % mod
    for i in range(2, N + 1):
        if (SA[i - 1] ** (A - 1) % mod) ** (A - 1) % mod == multiples[i - 1]:
            multiples[i] = multiples[i - 1]
        else:
            multiples[i] = (SA[i - 1] ** (A - 1) % mod) ** (A - 1) % mod
