            continue

        ahead = min(N-1, SA[i] + A - 1) - max(l, SA[i - 1]) + 1
        if ahead == 0:
            continue
        if (SA[i] ** A) * ((SA[i] + ahead) ** A) >= K:
            total += SA[i] ** A + (SA[i] + ahead) ** A 
            break

